// A framework this tool has never heard of, written for the fixture suite.
//
// Nothing in any package of flowatlas names it, and no adapter detects it. The
// whole of what makes its routes readable is the description in the fixture's
// `flowatlas.config.json`, which is the point the fixture exists to prove.
//
// Its spelling is deliberately its own: routes are declared on a server value,
// a child server is hung on a parent with `attach` rather than with the method
// that installs middleware, and the verbs are the ordinary ones.

export interface Request {
  params: Record<string, string>;
  query: Record<string, string>;
  body: unknown;
}

export interface Response {
  status(code: number): Response;
  json(body: unknown): Response;
}

export type Handler = (req: Request, res: Response) => unknown;

export declare class Server {
  get(path: string, ...handlers: Handler[]): Server;
  post(path: string, ...handlers: Handler[]): Server;
  put(path: string, ...handlers: Handler[]): Server;
  patch(path: string, ...handlers: Handler[]): Server;
  delete(path: string, ...handlers: Handler[]): Server;
  /** Middleware for the whole server, or for everything under one path. */
  use(pathOrHandler: string | Handler, ...handlers: Handler[]): Server;
  /** Hangs another server underneath this one at a path. */
  attach(path: string, child: Server): Server;
  listen(port: number): void;
}

export declare function createServer(): Server;
